{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text (always rendered for accessibility).",
      "required": true
    },
    {
      "name": "value",
      "type": "number | [number, number]",
      "description": "Current value: a `number` for single thumb mode or `[number, number]` for range mode.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(value: number) => void | (value: [number, number]) => void",
      "description": "Callback fired on value change during drag."
    },
    {
      "name": "onChangeEnd",
      "type": "(value: number) => void | (value: [number, number]) => void",
      "description": "Callback fired when drag ends."
    },
    {
      "name": "min",
      "type": "number",
      "description": "Minimum value.",
      "default": "0"
    },
    {
      "name": "max",
      "type": "number",
      "description": "Maximum value.",
      "default": "100"
    },
    {
      "name": "step",
      "type": "number",
      "description": "Step increment.",
      "default": "1"
    },
    {
      "name": "orientation",
      "type": "'horizontal' | 'vertical'",
      "description": "Orientation of the slider.",
      "default": "'horizontal'"
    },
    {
      "name": "formatValue",
      "type": "(value: number) => string",
      "description": "Custom value formatting function used for display and `aria-valuetext`."
    },
    {
      "name": "valueDisplay",
      "type": "'tooltip' | 'text' | 'none'",
      "description": "How the current value is displayed.",
      "default": "'tooltip'"
    },
    {
      "name": "marks",
      "type": "Array<{ value: number; label?: string }>",
      "description": "Tick marks at specified positions with optional labels. Unfilled marks use the track color; marks inside the filled region (at or behind the thumb, or between the thumbs in range mode) use the fill color."
    },
    {
      "name": "minStepsBetweenThumbs",
      "type": "number",
      "description": "Minimum number of steps between thumbs in range mode; prevents thumbs from overlapping.",
      "default": "0"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Whether the slider is disabled.",
      "default": "false"
    },
    {
      "name": "htmlName",
      "type": "string",
      "description": "The HTML name attribute for form submissions. Renders hidden inputs carrying the current value (two entries in range mode)."
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the slider is disabled. With isDisabled, shows a tooltip on hover/keyboard focus and keeps the thumb focusable via aria-disabled (value changes stay blocked). Use this instead of wrapping a disabled Slider in Tooltip. Disabled controls swallow the hover events an external Tooltip needs."
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Whether the field is optional.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Whether the field is required.",
      "default": "false"
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Whether to visually hide the label.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Description text rendered below the label."
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Status indicator object (`{ type, message }`) for validation feedback."
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text for an info icon displayed next to the label."
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the field container (label, control, and status together). No effect inside InputGroup (style the InputGroup instead) or in a `horizontal-labels` FormLayout. Root `xstyle`, `className`, and `style` are not accepted."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "description": "Class name for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "containerStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the element that paints the border and background and holds icons and end controls. Never the native input."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name for the visual control box."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the visual control box."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
